/**
 * Hand-built PDFs for the overlay tests.
 *
 * These are written byte by byte rather than produced by RipoDoc's own writer,
 * because the point of the overlay engine is reading files *other* tools made.
 * A corpus generated by the code under test would only prove the code agrees
 * with itself.
 *
 * The variants map onto the failure modes seen in real MSP reports:
 * cross-reference streams and object streams (any modern producer), page
 * rotation (scanned landscape reports), pre-existing annotations (a report
 * already carrying links), a junk prefix and a broken index (files mangled by
 * an email gateway or a careless editor).
 */

import { deflateSync } from 'node:zlib';

interface Obj {
  readonly id: number;
  readonly body: string;
}

const PAGE_CONTENT =
  'BT /F1 24 Tf 20 60 Td (412 97.4% 14) Tj ET\n' +
  'BT /F1 8 Tf 20 40 Td (Tickets resolved) Tj ET\n' +
  'BT /F1 8 Tf 20 20 Td [(May 1) -20 (48)] TJ ET\n';

const streamObject = (dictBody: string, data: string): string =>
  `<< ${dictBody} /Length ${Buffer.byteLength(data, 'latin1')} >>\nstream\n${data}\nendstream`;

const baseObjects = (options: {
  rotate?: number;
  mediaBox?: string;
  annots?: string;
  extraPageKeys?: string;
}): Obj[] => [
  { id: 1, body: '<< /Type /Catalog /Pages 2 0 R >>' },
  { id: 2, body: '<< /Type /Pages /Kids [3 0 R] /Count 1 >>' },
  {
    id: 3,
    body:
      '<< /Type /Page /Parent 2 0 R ' +
      `/MediaBox ${options.mediaBox ?? '[0 0 200 100]'} ` +
      `${options.rotate ? `/Rotate ${options.rotate} ` : ''}` +
      '/Resources << /Font << /F1 5 0 R >> >> ' +
      `${options.annots ?? ''}` +
      `${options.extraPageKeys ?? ''}` +
      '/Contents 4 0 R >>',
  },
  { id: 4, body: streamObject('', PAGE_CONTENT) },
  {
    id: 5,
    body: '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>',
  },
];

/** Assemble objects into a file with a classic cross-reference table. */
const assembleClassic = (
  objects: readonly Obj[],
  options: { prefix?: string; trailerExtra?: string; breakOffsets?: boolean } = {},
): Buffer => {
  const chunks: string[] = [];
  let offset = 0;
  const push = (text: string): void => {
    chunks.push(text);
    offset += Buffer.byteLength(text, 'latin1');
  };

  const prefix = options.prefix ?? '';
  push(prefix);
  const headerOffset = offset;
  push('%PDF-1.4\n');

  const sorted = [...objects].sort((a, b) => a.id - b.id);
  const offsets = new Map<number, number>();
  for (const object of sorted) {
    offsets.set(object.id, offset - headerOffset);
    push(`${object.id} 0 obj\n${object.body}\nendobj\n`);
  }

  const xrefOffset = offset - headerOffset;
  const size = (sorted[sorted.length - 1]?.id ?? 0) + 1;
  let xref = `xref\n0 ${size}\n0000000000 65535 f \n`;
  for (let id = 1; id < size; id += 1) {
    const at = options.breakOffsets ? 999_999 : (offsets.get(id) ?? 0);
    xref += `${String(at).padStart(10, '0')} 00000 n \n`;
  }
  push(xref);
  push(
    `trailer\n<< /Size ${size} /Root 1 0 R${options.trailerExtra ?? ''} >>\n` +
      `startxref\n${xrefOffset}\n%%EOF\n`,
  );

  return Buffer.from(chunks.join(''), 'latin1');
};

/** Apply the PNG `Up` predictor, as most real cross-reference streams do. */
const applyUpPredictor = (rows: readonly Buffer[]): Buffer => {
  const out: number[] = [];
  let previous: Buffer = Buffer.alloc(rows[0]?.length ?? 0);
  for (const row of rows) {
    out.push(2);
    for (let index = 0; index < row.length; index += 1) {
      out.push(((row[index] ?? 0) - (previous[index] ?? 0)) & 0xff);
    }
    previous = row;
  }
  return Buffer.from(out);
};

/**
 * The same document as a PDF 1.5 file: four objects inside an object stream,
 * indexed by a cross-reference stream.
 */
export const objectStreamPdf = (options: { predictor?: boolean } = {}): Buffer => {
  const objects = baseObjects({});
  const compressible = objects.filter((object) => object.id !== 4);
  const contentObject = objects.find((object) => object.id === 4);
  if (!contentObject) throw new Error('fixture is missing its content stream');

  let header = '';
  let body = '';
  for (const object of compressible) {
    header += `${object.id} ${body.length} `;
    body += `${object.body}\n`;
  }
  const objStmData = deflateSync(Buffer.from(header + body, 'latin1'));

  const chunks: Buffer[] = [];
  let offset = 0;
  const push = (value: string | Buffer): void => {
    const buffer = typeof value === 'string' ? Buffer.from(value, 'latin1') : value;
    chunks.push(buffer);
    offset += buffer.length;
  };

  push('%PDF-1.5\n');
  const contentOffset = offset;
  push(`4 0 obj\n${contentObject.body}\nendobj\n`);

  const objStmOffset = offset;
  push(
    `6 0 obj\n<< /Type /ObjStm /N ${compressible.length} /First ${header.length} ` +
      `/Filter /FlateDecode /Length ${objStmData.length} >>\nstream\n`,
  );
  push(objStmData);
  push('\nendstream\nendobj\n');

  const xrefOffset = offset;
  const row = (type: number, second: number, third: number): Buffer =>
    Buffer.from([type, (second >> 8) & 0xff, second & 0xff, third & 0xff]);

  // Ids 1, 2, 3 and 5 live inside object stream 6; 4, 6 and 7 are regular
  // objects. Types 1 and 2 therefore interleave, which is exactly the shape a
  // naive reader gets wrong.
  const ordered: Buffer[] = [
    row(0, 0, 255),
    row(2, 6, 0),
    row(2, 6, 1),
    row(2, 6, 2),
    row(1, contentOffset, 0),
    row(2, 6, 3),
    row(1, objStmOffset, 0),
    row(1, xrefOffset, 0),
  ];

  const raw = Buffer.concat(ordered);
  const encoded = options.predictor === false ? raw : applyUpPredictor(ordered);
  const data = deflateSync(encoded);
  const decodeParms =
    options.predictor === false ? '' : ' /DecodeParms << /Predictor 12 /Columns 4 >>';

  push(
    `7 0 obj\n<< /Type /XRef /Size 8 /Index [0 8] /W [1 2 1] /Root 1 0 R ` +
      `/Filter /FlateDecode${decodeParms} /Length ${data.length} >>\nstream\n`,
  );
  push(data);
  push('\nendstream\nendobj\n');
  push(`startxref\n${xrefOffset}\n%%EOF\n`);

  return Buffer.concat(chunks);
};

/** A plain, well-formed file with a classic cross-reference table. */
export const classicPdf = (): Buffer => assembleClassic(baseObjects({}));

/** A page displayed rotated 90° clockwise. */
export const rotatedPdf = (rotate: number): Buffer =>
  assembleClassic(baseObjects({ rotate }));

/** A page whose visible area is offset from the media box. */
export const croppedPdf = (): Buffer =>
  assembleClassic(
    baseObjects({ mediaBox: '[0 0 200 100]', extraPageKeys: '/CropBox [20 10 180 90] ' }),
  );

/** A report that already carries an annotation, referenced indirectly. */
export const annotatedPdf = (): Buffer =>
  assembleClassic([
    ...baseObjects({ annots: '/Annots 6 0 R ' }),
    { id: 6, body: '[7 0 R]' },
    {
      id: 7,
      body:
        '<< /Type /Annot /Subtype /Link /Rect [0 0 10 10] /Border [0 0 0] ' +
        '/A << /S /URI /URI (https://example.test/existing) >> >>',
    },
  ]);

/** A page dictionary carrying producer-specific keys that must survive. */
export const exoticKeysPdf = (): Buffer =>
  assembleClassic(
    baseObjects({
      extraPageKeys:
        '/StructParents 0 /Tabs /S /Group << /S /Transparency /CS /DeviceRGB >> ' +
        '/Producer#20Note (kept (verbatim) \\) here) ',
    }),
  );

/** Bytes before `%PDF-`, as some mail gateways produce. */
export const prefixedPdf = (): Buffer =>
  assembleClassic(baseObjects({}), { prefix: 'GARBAGE BYTES\r\n' });

/** Every cross-reference offset is wrong; a viewer rebuilds by scanning. */
export const brokenXrefPdf = (): Buffer =>
  assembleClassic(baseObjects({}), { breakOffsets: true });

/** Declares encryption, which RipoDoc must refuse rather than strip. */
export const encryptedPdf = (): Buffer =>
  assembleClassic(baseObjects({}), { trailerExtra: ' /Encrypt 9 0 R' });

export const CONTENT_TEXT = PAGE_CONTENT;
